""" Gets the last `size` bytes of the stacktrace """
def _stacktrace_end(stacktrace: Any, size: Any) -> object {
    stacktrace_length = len(stacktrace);
    if (stacktrace_length <= size) {
        return stacktrace;
    }
    return stacktrace[:-(stacktrace_length - size)];
}

